# Source this in every shell that talks to the cars:   source <ws>/install/fleet_viewer/share/fleet_viewer/env/fleet_env.sh
# - ROS 2 Jazzy + this workspace
# - CycloneDDS on the shared fleet domain (1), bound to this PC's Wi-Fi interface, discovery-only multicast
#   (Wi-Fi multicast drops video). Override the interface with FLEET_IFACE=<name>.
source /opt/ros/jazzy/setup.bash
_ws=$(cd "$(dirname "${BASH_SOURCE[0]}")/../../../.." && pwd)        # <ws>/install
[ -f "$_ws/setup.bash" ] && source "$_ws/setup.bash"

if [ -z "$FLEET_IFACE" ]; then
    for _d in /sys/class/net/*/wireless; do FLEET_IFACE=$(basename "$(dirname "$_d")"); break; done
fi
[ -n "$FLEET_IFACE" ] || { echo "fleet_env: no Wi-Fi interface found; set FLEET_IFACE" >&2; return 1; }
mkdir -p ~/.ros
cat > ~/.ros/cyclonedds_fleet.xml <<XML
<?xml version="1.0" encoding="UTF-8" ?>
<!-- generated by fleet_viewer/env/fleet_env.sh -->
<CycloneDDS xmlns="https://cdds.io/config">
  <Domain id="any">
    <General>
      <Interfaces><NetworkInterface name="$FLEET_IFACE" priority="default" multicast="default"/></Interfaces>
      <AllowMulticast>spdp</AllowMulticast>
    </General>
  </Domain>
</CycloneDDS>
XML
export RMW_IMPLEMENTATION=rmw_cyclonedds_cpp
export ROS_DOMAIN_ID=1
export ROS_AUTOMATIC_DISCOVERY_RANGE=SUBNET
export CYCLONEDDS_URI=file://$HOME/.ros/cyclonedds_fleet.xml
export FLEET_IFACE
